# ==============================================================================# 097_NEGOTIATION_ENGINE.py## IOTEC NEGOTIATION ENGINE## Missão:# Registrar todo o histórico de negociação comercial.# ==============================================================================from __future__ import annotationsimport sqlite3import uuidimport hashlibimport jsonfrom pathlib import Pathfrom datetime import datetimeDB = Path("iotec.db")class NegotiationEngine:    EVENTS = {        "PROPOSAL_SENT",        "CLIENT_VIEWED",        "CLIENT_REPLIED",        "COUNTER_OFFER",        "DISCOUNT_REQUEST",        "PRICE_APPROVED",        "PRICE_REJECTED",        "NEGOTIATION_WON",        "NEGOTIATION_LOST"    }    def __init__(self):        self.conn = sqlite3.connect(DB)        self.conn.row_factory = sqlite3.Row        self.conn.execute("""        CREATE TABLE IF NOT EXISTS commercial_negotiations(            id INTEGER PRIMARY KEY AUTOINCREMENT,            negotiation_uuid TEXT UNIQUE,            proposal_uuid TEXT,            opportunity_uuid TEXT,            event_type TEXT,            old_value REAL,            new_value REAL,            discount REAL,            notes TEXT,            performed_by TEXT,            status TEXT,            created_at TEXT,            metadata TEXT,            hash TEXT        )        """)        self.conn.commit()    # ---------------------------------------------------------------------    def _sha(self, obj):        raw = json.dumps(            obj,            ensure_ascii=False,            sort_keys=True        )        return hashlib.sha256(raw.encode()).hexdigest()    # ---------------------------------------------------------------------    def register_event(        self,        proposal_uuid,        opportunity_uuid,        event_type,        old_value=None,        new_value=None,        notes="",        performed_by="IOTEC"    ):        if event_type not in self.EVENTS:            raise RuntimeError("Evento inválido.")        desconto = None        if old_value is not None and new_value is not None:            desconto = old_value - new_value        payload = {            "negotiation_uuid": str(uuid.uuid4()),            "proposal_uuid": proposal_uuid,            "opportunity_uuid": opportunity_uuid,            "event_type": event_type,            "old_value": old_value,            "new_value": new_value,            "discount": desconto,            "notes": notes,            "performed_by": performed_by,            "status": "REGISTERED",            "created_at": datetime.utcnow().isoformat(),            "metadata": {                "origin":"097_NEGOTIATION_ENGINE"            }        }        assinatura = self._sha(payload)        self.conn.execute("""        INSERT INTO commercial_negotiations(            negotiation_uuid,            proposal_uuid,            opportunity_uuid,            event_type,            old_value,            new_value,            discount,            notes,            performed_by,            status,            created_at,            metadata,            hash        )        VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)        """,(            payload["negotiation_uuid"],            payload["proposal_uuid"],            payload["opportunity_uuid"],            payload["event_type"],            payload["old_value"],            payload["new_value"],            payload["discount"],            payload["notes"],            payload["performed_by"],            payload["status"],            payload["created_at"],            json.dumps(payload["metadata"], ensure_ascii=False),            assinatura        ))        self.conn.commit()        payload["hash"] = assinatura        return payload# ==============================================================================# TESTE# ==============================================================================if __name__ == "__main__":    conn = sqlite3.connect(DB)    conn.row_factory = sqlite3.Row    proposta = conn.execute("""        SELECT proposal_uuid,               opportunity_uuid,               estimated_value        FROM commercial_proposals        LIMIT 1    """).fetchone()    if proposta is None:        raise RuntimeError("Nenhuma proposta encontrada.")    engine = NegotiationEngine()    resultado = engine.register_event(        proposal_uuid=proposta["proposal_uuid"],        opportunity_uuid=proposta["opportunity_uuid"],        event_type="COUNTER_OFFER",        old_value=proposta["estimated_value"],        new_value=9000.00,        notes="Cliente solicitou desconto comercial."    )    print("="*80)    print("NEGOTIATION ENGINE")    print("="*80)    for k, v in resultado.items():        print(f"{k:20}: {v}")    print("="*80)